/* ---------- helpers ---------- */
const trunc=(v,n)=>{const x=String(v==null?'':v);return x.length>n?x.slice(0,n-3)+'...':x;};
const esc=v=>String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
