const rule=()=>blocks.push({type:'divider'});
const group=(title,body,limit,meta)=>blocks.push({type:'section',text:{type:'mrkdwn',text:trunc('*'+title+'*'+(meta?('  '+meta):'')+'\n\n'+body,limit||2600)}});

