const SRC={hubspot_company:'HubSpot',official_website:'their website',official_site:'their website',identity_aligned_public_search:'public source',public_search:'public source',booth_notes:'booth notes',scanner:'booth notes',ai_from_public_source:'AI, from a public source',ai_inferred:'AI estimate',not_established:'not found',unknown:'unresolved'};
