const email=s.email||(crm.existing_contact||{}).email||'email missing';
const repeatScan=s.repeat_scan===true;
const scanNo=Number(s.scan_count||(repeatScan?2:1));

blocks.push({type:'header',text:{type:'plain_text',text:trunc(tier+' · '+full+flag,150),emoji:true}});
